// Extract message text from various WhatsApp bridge formats
// Supports: Evolution API, Baileys, WA Web Plus, Tasker, generic
const body = $input.item.json.body || $input.item.json;

let messageText = '';
let senderName = '';
let senderPhone = '';
let timestamp = new Date().toISOString();

// Evolution API format
if (body.data && body.data.message) {
  messageText = body.data.message.conversation 
    || body.data.message.extendedTextMessage?.text 
    || '';
  senderName = body.data.pushName || '';
  senderPhone = body.data.key?.remoteJid?.replace('@s.whatsapp.net', '') || '';
  timestamp = new Date(body.data.messageTimestamp * 1000).toISOString();
}
// Baileys / generic format
else if (body.message) {
  messageText = body.message.conversation 
    || body.message.extendedTextMessage?.text 
    || body.message || '';
  senderName = body.pushName || body.senderName || '';
  senderPhone = body.from || body.sender || '';
}
// Simple text format (Tasker, custom)
else if (body.text) {
  messageText = body.text;
  senderName = body.sender || body.from || 'Unknown';
  senderPhone = body.phone || '';
}
// Plain string body
else if (typeof body === 'string') {
  messageText = body;
}

// Skip empty messages or media-only messages
if (!messageText || messageText.trim().length < 20) {
  return [{ json: { skip: true, reason: 'Message too short or empty' } }];
}

return [{
  json: {
    message_text: messageText,
    sender_name: senderName,
    sender_phone: senderPhone,
    timestamp: timestamp,
    source: 'whatsapp',
    skip: false
  }
}];

// Parse and clean the Gemini AI response
const item = $input.item;
let jsonString = '';

// Handle different Gemini response formats
if (item.json.text) {
  jsonString = item.json.text;
} else if (item.json.content && item.json.content.parts) {
  jsonString = item.json.content.parts[0].text;
} else if (item.json.output) {
  jsonString = item.json.output;
} else {
  jsonString = JSON.stringify(item.json);
}

// Remove markdown code block delimiters
jsonString = jsonString.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/, '')
  .trim();

try {
  const parsed = JSON.parse(jsonString);

  // Normalize: ensure we always have is_relevant and vessels array
  if (Array.isArray(parsed)) {
    return { json: { is_relevant: true, vessels: parsed } };
  }
  if (parsed.vessel_name) {
    return { json: { is_relevant: true, vessels: [parsed] } };
  }
  return { json: parsed };
} catch (error) {
  return { json: { is_relevant: false, vessels: [], error: 'JSON parse failed: ' + error.message } };
}

// Split vessels array into individual items and add source metadata
const vessels = $input.item.json.vessels || [];
const senderName = $('Parse WhatsApp Message').item.json.sender_name || 'Unknown';
const senderPhone = $('Parse WhatsApp Message').item.json.sender_phone || '';
const timestamp = $('Parse WhatsApp Message').item.json.timestamp || new Date().toISOString();

const results = [];

for (const vessel of vessels) {
  // Set source fields
  vessel.source = 'whatsapp';
  vessel.source_identifier = `wa-${senderPhone}-${Date.now()}`;
  vessel.last_seen_at = timestamp;
  vessel.first_seen_at = timestamp;

  // Use sender name as owner_manager if not provided
  if (!vessel.owner_manager) {
    vessel.owner_manager = senderName;
  }

  // Clean vessel name — ensure MV prefix
  if (vessel.vessel_name && !vessel.vessel_name.toUpperCase().startsWith('MV ')) {
    vessel.vessel_name = 'MV ' + vessel.vessel_name;
  }

  // Ensure vessel_name is uppercase
  if (vessel.vessel_name) {
    vessel.vessel_name = vessel.vessel_name.toUpperCase();
  }

  // Convert arrays to strings for Supabase text columns
  if (Array.isArray(vessel.last_5_cargoes)) {
    vessel.last_5_cargoes = vessel.last_5_cargoes.join(', ');
  }
  if (Array.isArray(vessel.special_features)) {
    vessel.special_features = vessel.special_features.join(', ');
  }

  results.push({ json: vessel });
}

return results;
